CREATE POLICY saves_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY saves_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY saves_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text) WITH CHECK(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY saves_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='player-saves' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE TABLE public.rtc_rooms (id uuid PRIMARY KEY, host_id uuid NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '1 hour');
GRANT ALL ON public.rtc_rooms TO service_role;
ALTER TABLE public.rtc_rooms ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rtc_members(room_id uuid REFERENCES public.rtc_rooms(id) ON DELETE CASCADE, peer_id uuid NOT NULL, user_id uuid NOT NULL, name text NOT NULL, seen_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(room_id,peer_id));
GRANT ALL ON public.rtc_members TO service_role;
ALTER TABLE public.rtc_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.rtc_signals(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, room_id uuid REFERENCES public.rtc_rooms(id) ON DELETE CASCADE, sender uuid NOT NULL, recipient uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('offer','answer','ice')), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.rtc_signals TO service_role;
ALTER TABLE public.rtc_signals ENABLE ROW LEVEL SECURITY;
CREATE INDEX rtc_recipient ON public.rtc_signals(room_id,recipient,id);
CREATE FUNCTION public.rtc_exchange(_room uuid,_peer uuid,_op text DEFAULT 'poll',_name text DEFAULT '',_since bigint DEFAULT 0,_to uuid DEFAULT NULL,_kind text DEFAULT NULL,_payload jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE owner uuid; result jsonb; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na conta'; END IF;
IF _op NOT IN ('poll','signal','leave') THEN RAISE EXCEPTION 'Invalid operation'; END IF;
DELETE FROM rtc_rooms WHERE expires_at<now();
IF _op='poll' THEN
INSERT INTO rtc_rooms(id,host_id) VALUES(_room,auth.uid()) ON CONFLICT DO NOTHING;
PERFORM 1 FROM rtc_rooms WHERE id=_room FOR UPDATE;
SELECT user_id INTO owner FROM rtc_members WHERE room_id=_room AND peer_id=_peer;
IF owner IS NOT NULL AND owner<>auth.uid() THEN RAISE EXCEPTION 'Peer ownership mismatch'; END IF;
DELETE FROM rtc_members WHERE room_id=_room AND seen_at<now()-interval '30 seconds';
IF owner IS NULL AND (SELECT count(*) FROM rtc_members WHERE room_id=_room)>=4 THEN RAISE EXCEPTION 'Room full'; END IF;
INSERT INTO rtc_members(room_id,peer_id,user_id,name) VALUES(_room,_peer,auth.uid(),left(_name,50)) ON CONFLICT(room_id,peer_id) DO UPDATE SET seen_at=now();
DELETE FROM rtc_signals WHERE room_id=_room AND created_at<now()-interval '2 minutes';
SELECT jsonb_build_object('peers',coalesce((SELECT jsonb_agg(jsonb_build_object('id',peer_id,'name',name)) FROM rtc_members WHERE room_id=_room),'[]'::jsonb),'signals',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'from',sender,'kind',kind,'payload',payload) ORDER BY id) FROM (SELECT * FROM rtc_signals WHERE room_id=_room AND recipient=_peer AND id>_since ORDER BY id LIMIT 100)s),'[]'::jsonb)) INTO result;
RETURN result;
END IF;
IF NOT EXISTS(SELECT 1 FROM rtc_members WHERE room_id=_room AND peer_id=_peer AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Not a member'; END IF;
IF _op='leave' THEN DELETE FROM rtc_members WHERE room_id=_room AND peer_id=_peer; RETURN '{}'::jsonb; END IF;
IF NOT EXISTS(SELECT 1 FROM rtc_members WHERE room_id=_room AND peer_id=_to AND seen_at>now()-interval '30 seconds') THEN RAISE EXCEPTION 'Recipient unavailable'; END IF;
IF _kind NOT IN ('offer','answer','ice') OR octet_length(_payload::text)>32768 THEN RAISE EXCEPTION 'Invalid signal'; END IF;
IF (SELECT count(*) FROM rtc_signals WHERE sender=_peer AND created_at>now()-interval '1 second')>=30 THEN RAISE EXCEPTION 'Too many signals'; END IF;
INSERT INTO rtc_signals(room_id,sender,recipient,kind,payload) VALUES(_room,_peer,_to,_kind,_payload); RETURN '{}'::jsonb;
END $$;
REVOKE ALL ON FUNCTION public.rtc_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.rtc_exchange(uuid,uuid,text,text,bigint,uuid,text,jsonb) TO authenticated;
CREATE TABLE public.challenge_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, day date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, step integer NOT NULL DEFAULT 0, score integer NOT NULL DEFAULT 0, last_hit timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.challenge_runs TO authenticated; GRANT ALL ON public.challenge_runs TO service_role;
ALTER TABLE public.challenge_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_challenges ON public.challenge_runs FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.start_daily_challenge() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r challenge_runs; n integer; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre para competir'; END IF; PERFORM pg_advisory_xact_lock(hashtext(auth.uid()::text)); SELECT count(*) INTO n FROM challenge_runs WHERE user_id=auth.uid() AND day=(now() AT TIME ZONE 'UTC')::date; IF n>=3 THEN RAISE EXCEPTION 'Suas três tentativas de hoje acabaram'; END IF; INSERT INTO challenge_runs(user_id) VALUES(auth.uid()) RETURNING * INTO r; RETURN jsonb_build_object('id',r.id,'step',0,'score',0,'target',extract(doy FROM r.day)::integer%4,'remaining',3-n-1); END $$;
REVOKE ALL ON FUNCTION public.start_daily_challenge() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.start_daily_challenge() TO authenticated;
CREATE FUNCTION public.hit_daily_target(_run uuid,_direction integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r challenge_runs; expected integer; elapsed numeric; BEGIN SELECT * INTO r FROM challenge_runs WHERE id=_run AND user_id=auth.uid() FOR UPDATE; IF r.id IS NULL OR r.finished_at IS NOT NULL THEN RAISE EXCEPTION 'Partida encerrada'; END IF; IF r.day<>(now() AT TIME ZONE 'UTC')::date OR now()-r.started_at>interval '60 seconds' THEN UPDATE challenge_runs SET finished_at=now() WHERE id=r.id; RETURN jsonb_build_object('done',true,'score',r.score,'step',r.step); END IF; expected=(extract(doy FROM r.day)::integer+r.step*7)%4; elapsed=extract(epoch FROM now()-r.last_hit)*1000; IF elapsed<150 THEN RAISE EXCEPTION 'Aguarde o próximo alvo'; END IF; UPDATE challenge_runs SET step=step+1,score=score+CASE WHEN _direction=expected THEN greatest(10,100-floor(elapsed/50)::integer) ELSE 0 END,last_hit=now(),finished_at=CASE WHEN step+1>=20 THEN now() ELSE NULL END WHERE id=r.id RETURNING * INTO r; RETURN jsonb_build_object('done',r.finished_at IS NOT NULL,'step',r.step,'score',r.score,'target',(extract(doy FROM r.day)::integer+r.step*7)%4); END $$;
REVOKE ALL ON FUNCTION public.hit_daily_target(uuid,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.hit_daily_target(uuid,integer) TO authenticated;
CREATE FUNCTION public.daily_challenge_board() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(t),'[]'::jsonb) FROM (SELECT p.display_name,max(r.score) AS score FROM challenge_runs r JOIN profiles p ON p.id=r.user_id WHERE r.day=(now() AT TIME ZONE 'UTC')::date AND r.finished_at IS NOT NULL AND p.leaderboard_enabled GROUP BY p.id,p.display_name ORDER BY max(r.score) DESC LIMIT 20)t $$;
REVOKE ALL ON FUNCTION public.daily_challenge_board() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.daily_challenge_board() TO anon,authenticated;